import{_ as t,o as a,c as r,ae as o}from"./chunks/framework.Dn6zxbF8.js";const g=JSON.parse('{"title":"AWS: exposure and health checks","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/1008684393/references/aws.md","filePath":"adrs/1008684393/references/aws.md"}'),s={name:"adrs/1008684393/references/aws.md"};function n(c,e,d,l,i,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="aws-exposure-and-health-checks" tabindex="-1">AWS: exposure and health checks <a class="header-anchor" href="#aws-exposure-and-health-checks" aria-label="Permalink to &quot;AWS: exposure and health checks&quot;">​</a></h1><p>Verified against primary documentation on 2026-10-11.</p><h2 id="exposure" tabindex="-1">Exposure <a class="header-anchor" href="#exposure" aria-label="Permalink to &quot;Exposure&quot;">​</a></h2><p>Load balancers have a <strong>scheme</strong> of <code>internet-facing</code> or <code>internal</code>. The nodes of an internet-facing load balancer have public IP addresses; the nodes of an internal one &quot;have only private IP addresses&quot; and &quot;can only route requests from clients with access to the VPC&quot;. AWS gives multi-tier applications as the reason: web servers face the internet, database servers only the web servers (<a href="https://docs.aws.amazon.com/elasticloadbalancing/latest/classic/elb-internal-load-balancers.html" target="_blank" rel="noreferrer">Internal load balancers</a>).</p><p>Subnets are <strong>public</strong> when their route table sends internet traffic to an internet gateway and <strong>private</strong> when it does not (<a href="https://docs.aws.amazon.com/vpc/latest/userguide/VPC_Internet_Gateway.html" target="_blank" rel="noreferrer">Internet gateways</a>).</p><p>On EKS, the AWS Load Balancer Controller takes the same values through <code>alb.ingress.kubernetes.io/scheme</code> and <code>service.beta.kubernetes.io/aws-load-balancer-scheme</code> (<a href="https://kubernetes-sigs.github.io/aws-load-balancer-controller/latest/guide/service/annotations/" target="_blank" rel="noreferrer">Load Balancer Controller annotations</a>). The cluster API server endpoint is <strong>public</strong>, <strong>private</strong> or both (<a href="https://docs.aws.amazon.com/eks/latest/userguide/cluster-endpoint.html" target="_blank" rel="noreferrer">Cluster API server endpoint</a>).</p><p>API Gateway endpoints are edge-optimized, Regional or private, chosen by &quot;where the majority of your API traffic originates from&quot; (<a href="https://docs.aws.amazon.com/apigateway/latest/developerguide/api-gateway-api-endpoint-types.html" target="_blank" rel="noreferrer">API endpoint types</a>). App Runner services have a <strong>public endpoint</strong> or a <strong>private endpoint</strong> reached through a VPC Ingress Connection (<a href="https://docs.aws.amazon.com/apprunner/latest/dg/network-pl.html" target="_blank" rel="noreferrer">Enabling private endpoints</a>).</p><h2 id="one-port-for-grpc-and-http" tabindex="-1">One port for gRPC and HTTP <a class="header-anchor" href="#one-port-for-grpc-and-http" aria-label="Permalink to &quot;One port for gRPC and HTTP&quot;">​</a></h2><p>An Application Load Balancer target group has a protocol version of HTTP/1.1, HTTP/2 or gRPC, and each accepts only some client protocols (<a href="https://docs.aws.amazon.com/elasticloadbalancing/latest/application/load-balancer-target-groups.html" target="_blank" rel="noreferrer">Target groups for Application Load Balancers</a>):</p><table tabindex="0"><thead><tr><th>Client sends</th><th><code>HTTP1</code> target group</th><th><code>HTTP2</code> target group</th><th><code>GRPC</code> target group</th></tr></thead><tbody><tr><td>HTTP/1.1</td><td>success</td><td>error</td><td>error</td></tr><tr><td>HTTP/2</td><td>success</td><td>success</td><td>success for <code>POST</code></td></tr><tr><td>gRPC</td><td>error</td><td>success if targets speak gRPC</td><td>success</td></tr></tbody></table><p>No single target group accepts both HTTP/1.1 clients and gRPC. A gRPC target group lets the load balancer route &quot;based on the package, service, and method&quot;, so a port that carries both is served by two target groups pointing at it: a gRPC one behind listener rules for the gRPC paths, and an HTTP/1.1 one for everything else. Both versions need an HTTPS listener.</p><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>Network reach and identity are separate settings. Lambda function URLs take an auth type of <code>AWS_IAM</code> or <code>NONE</code> (<a href="https://docs.aws.amazon.com/lambda/latest/dg/urls-auth.html" target="_blank" rel="noreferrer">Function URL auth</a>). VPC Lattice groups services into a <strong>service network</strong> for reach and attaches <strong>auth policies</strong> for identity, denying all traffic once auth is on and no policy allows it (<a href="https://docs.aws.amazon.com/vpc-lattice/latest/ug/auth-policies.html" target="_blank" rel="noreferrer">Auth policies</a>).</p><p>Staff tools sit behind AWS Verified Access, whose controls &quot;do not depend on traditional network controls or network perimeters&quot; (<a href="https://docs.aws.amazon.com/verified-access/latest/ug/how-it-works.html" target="_blank" rel="noreferrer">How Verified Access works</a>).</p><h2 id="health-checks" tabindex="-1">Health checks <a class="header-anchor" href="#health-checks" aria-label="Permalink to &quot;Health checks&quot;">​</a></h2><p>HTTP target group health checks request <code>/</code> and expect <code>200</code> by default. gRPC target group health checks call <code>/AWS.ALB/healthcheck</code> and expect <code>12</code>, <code>UNIMPLEMENTED</code>, by default, so a service that implements no health method at all still passes. Checking <code>grpc.health.v1</code> takes setting the path to <code>/grpc.health.v1.Health/Check</code> and the success code to <code>0</code> (<a href="https://docs.aws.amazon.com/elasticloadbalancing/latest/application/target-group-health-checks.html" target="_blank" rel="noreferrer">Target group health checks</a>).</p><p>The load balancer runs its own check and does not read the Pod&#39;s <code>readinessProbe</code>. Pod readiness gates, enabled with the <code>elbv2.k8s.aws/pod-readiness-gate-inject</code> namespace label, hold a Pod not ready until the load balancer reports it healthy, so a rollout does not remove old Pods before new ones receive traffic. AWS recommends load balancer health checks alongside Kubernetes probes, not in place of them (<a href="https://docs.aws.amazon.com/eks/latest/best-practices/load-balancing.html" target="_blank" rel="noreferrer">EKS best practices: load balancing</a>).</p><p>The same guide says not to make liveness depend on anything outside the Pod, and warns that &quot;readiness probes that depend on external factors, such as connectivity to a database, can cause all pods to fail the probe&quot;, leading to an outage or a cascading failure. AWS also advises against giving liveness and readiness the same specification (<a href="https://docs.aws.amazon.com/prescriptive-guidance/latest/ha-resiliency-amazon-eks-apps/probes-checks.html" target="_blank" rel="noreferrer">Probes and checks</a>).</p>',18)])])}const u=t(s,[["render",n]]);export{g as __pageData,u as default};
